      "implementation": "Renders <form> — Enter-to-submit, browser validation, and autocomplete all work",
      "userRequirements": "Every control needs an accessible name (FormField provides it)"
    },
    {
      "feature": "Even spacing is tokenized",
      "implementation": "gap defaults to the md token and accepts exact pixels — rhythm stays consistent across forms",
      "userRequirements": "Keep related fields closer (smaller gap) than unrelated groups (use FormLayout/Fieldset to group)"
    }
  ],
  "compositionRules": [
    {
      "component": "FormField",
      "relationship": "Each field is a FormField; Form spaces them evenly",
      "example": "<Form onSubmit={save}><FormField …>…</FormField></Form>"
    },
    {
